<script>
(function(){
  var _cs = document.currentScript;
  var svg = document.createElementNS("http://www.w3.org/2000/svg","svg");
  svg.setAttribute("viewBox","0 0 680 300");
  svg.setAttribute("width","100%");
  var FONT = "-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif";
  function el(tag, attrs, txt){ var e = document.createElementNS("http://www.w3.org/2000/svg", tag); for (var k in attrs) e.setAttribute(k, attrs[k]); if (txt !== undefined) e.textContent = txt; return e; }
  function tx(s, a){ a["font-family"] = FONT; return el("text", a, s); }
  function fmt(v, d){ var p = v.toFixed(d).split("."); p[0] = p[0].replace(/\B(?=(\d{3})+(?!\d))/g, "\u00a0"); return p.join(","); }
  var CFG = {"data":[35491.27,35874.26,35806.65,36009.4,36335.61,35751.43,35706.46,35800.89,35489.86,35460.27,35235.87,35154.76,35502.65,35518.55,35649.51,35041.86,35145.38,35664.62,35983.98,35584.46,36137.1,36176.55,35928.63,36107.96,36324.99],"labels":["16 sept.","17 sept.","18 sept.","21 sept.","22 sept.","23 sept.","24 sept.","25 sept.","28 sept.","29 sept.","30 sept.","1 oct.","2 oct.","5 oct.","6 oct.","7 oct.","8 oct.","9 oct.","13 oct.","14 oct.","15 oct.","16 oct.","19 oct.","20 oct.","21 oct."],"lblIdx":[0,4,8,11,15,19,24],"bands":[{"from":4,"to":15,"color":"#c0392b","op":0.05,"label":"REPLI -3,6\u00a0%"},{"from":15,"to":24,"color":"#2e7d32","op":0.07,"label":"REBOND +3,7\u00a0%"}],"refs":[{"v":35041.86,"color":"#7a3030","label":"PLUS BAS 7 OCT 35\u00a0041,86"}],"events":[{"i":17,"lines":["9 OCT","EPA\u00a0: 68\u00a0300","EMPL. PERDUS"]},{"i":22,"lines":["19 OCT","IPC 3,1\u00a0%","PRÉV. 3,2\u00a0%"]}],"pill":"36\u00a0324,99","step":250,"dig":0,"gap":12};
  var data = CFG.data;
  var margin = {left: 62, right: 24, top: 18, bottom: 46};
  var PW = 680 - margin.left - margin.right;
  var PH = 300 - margin.top - margin.bottom;
  var MT = margin.top;
  var n = data.length;
  var vmin = Math.min.apply(null, data), vmax = Math.max.apply(null, data);
  var pad = (vmax - vmin) * 0.12;
  var ymin = Math.floor((vmin - pad) / CFG.step) * CFG.step;
  var ymax = Math.ceil((vmax + pad) / CFG.step) * CFG.step;
  function xp(i){ return margin.left + (i / (n - 1)) * PW; }
  function yp(v){ return MT + PH - ((v - ymin) / (ymax - ymin)) * PH; }
  var lastX = xp(n - 1), lastY = yp(data[n - 1]);
  var currentVal = data[n - 1];
  var labelsLayer = [];

  CFG.bands.forEach(function(b){
    var x1 = xp(b.from), x2 = xp(b.to);
    svg.appendChild(el("rect", {x: x1, y: MT, width: x2 - x1, height: PH, fill: b.color, "fill-opacity": b.op}));
    labelsLayer.push(tx(b.label, {x: (x1 + x2) / 2, y: MT + 8, "text-anchor": "middle", "font-size": 7, "font-weight": 700, fill: b.color}));
  });

  var t, yTicks = [];
  for (t = ymin; t <= ymax; t += CFG.step) { if (Math.abs(t - currentVal) > CFG.step * 0.2) yTicks.push(t); }
  yTicks.forEach(function(v){
    svg.appendChild(el("line", {x1: margin.left, x2: margin.left + PW, y1: yp(v), y2: yp(v), stroke: "#ececec", "stroke-width": 0.5}));
    labelsLayer.push(tx(fmt(v, 0), {x: margin.left - 6, y: yp(v) + 3, "text-anchor": "end", "font-size": 8.5, fill: "#aaaaaa"}));
  });

  var refYs = [];
  CFG.refs.forEach(function(r){
    var ry = yp(r.v);
    refYs.push(ry);
    svg.appendChild(el("line", {x1: margin.left, x2: margin.left + PW, y1: ry, y2: ry, stroke: r.color, "stroke-width": 1, "stroke-dasharray": "3,3"}));
    if (Math.abs(r.v - currentVal) / currentVal >= 0.03) {
      labelsLayer.push(tx(r.label, {x: margin.left + 10, y: ry - 10, "text-anchor": "start", "font-size": 7, "font-weight": 700, fill: r.color}));
    }
  });

  var d = "";
  data.forEach(function(v, i){ d += (i === 0 ? "M" : "L") + xp(i).toFixed(2) + " " + yp(v).toFixed(2) + " "; });
  svg.appendChild(el("path", {d: d, fill: "none", stroke: "#4a5568", "stroke-width": 1.6, "stroke-linejoin": "round"}));

  svg.appendChild(el("line", {x1: margin.left, x2: margin.left, y1: MT, y2: MT + PH, stroke: "#d8d8d8", "stroke-width": 1}));
  svg.appendChild(el("line", {x1: margin.left, x2: margin.left + PW, y1: MT + PH, y2: MT + PH, stroke: "#d8d8d8", "stroke-width": 1}));

  CFG.lblIdx.forEach(function(i, k){
    var anchor = (i === 0) ? "start" : (i === n - 1 ? "end" : "middle");
    labelsLayer.push(tx(CFG.labels[i], {x: xp(i), y: MT + PH + 14, "text-anchor": anchor, "font-size": 8, fill: "#999999"}));
  });

  var floorY = refYs.length ? Math.min.apply(null, refYs) - CFG.gap : MT + PH - CFG.gap;
  CFG.events.forEach(function(ev){
    var ex = xp(ev.i);
    svg.appendChild(el("line", {x1: ex, x2: ex, y1: MT, y2: MT + PH, stroke: "#1a3560", "stroke-opacity": 0.5, "stroke-width": 1, "stroke-dasharray": "2,3"}));
    var crowded = CFG.events.some(function(o){ return o.i !== ev.i && Math.abs(xp(o.i) - ex) < 85; });
    var longest = 0;
    ev.lines.forEach(function(l){ longest = Math.max(longest, Math.ceil(l.length * 7 * 0.68)); });
    var nearRight = (ex + longest + 3) > (margin.left + PW);
    var anchor = (crowded || nearRight) ? "end" : "start";
    var lx = (anchor === "end") ? ex - 3 : ex + 3;
    var yStart = floorY - (ev.lines.length - 1) * 9 - (crowded ? 30 : 0);
    ev.lines.forEach(function(l, k){
      labelsLayer.push(tx(l, {x: lx, y: yStart + k * 9, "text-anchor": anchor, "font-size": 7, "font-weight": 700, fill: "#1a3560"}));
    });
  });

  svg.appendChild(el("circle", {cx: lastX, cy: lastY, r: 4, fill: "#4a5568"}));

  var pillText = CFG.pill;
  var pillW = Math.ceil(pillText.length * 9 * 0.58) + 10;
  var pillH = 16;
  var pillX = lastX - pillW - 6;
  var pillY = lastY - pillH / 2;
  if (pillX < margin.left) pillX = margin.left;
  svg.appendChild(el("rect", {x: pillX, y: pillY, width: pillW, height: pillH, rx: 3, fill: "#e8a825"}));
  svg.appendChild(tx(pillText, {x: pillX + pillW / 2, y: pillY + pillH / 2 + 3.5, "text-anchor": "middle", "font-size": 9, "font-weight": 700, fill: "#111111"}));

  labelsLayer.forEach(function(e){ svg.appendChild(e); });
  _cs.parentNode.appendChild(svg);
})();
</script>
</div>
<div style="font-family:-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif;font-size:10px;color:#999;padding:4px 14px 10px;font-style:italic;">Source&nbsp;: YCharts, indice composé S&amp;P/TSX, clôture quotidienne, 16 sept. au 21 oct. 2026&nbsp;; Statistique Canada. &nbsp;|&nbsp; hdq.ca</div>
</div>
</div>
<p style="font-size:11px;color:#666;font-family:-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif;margin-top:6px;">L’annotation du 9 octobre signale l’Enquête sur la population active, qui a fait état de 68&nbsp;300 pertes nettes d’emplois en septembre. Celle du 19 octobre signale la publication de l’IPC de septembre, à 3,1&nbsp;% contre un consensus de 3,2&nbsp;% selon un sondage de Reuters.</p>
<p>L’indice se situe donc 10,62 points sous sa clôture du 22 septembre. Six des 24 variations quotidiennes entre le 16 septembre et le 21 octobre ont dépassé 1&nbsp;%, et la série a changé de direction 12 fois.</p>
<p>Un investisseur qui a évalué son portefeuille à la clôture du 7 octobre faisait face à une perte de 3,6&nbsp;% par rapport au niveau du 22 septembre. Celui qui l’a évalué à la clôture du 21 octobre ne voyait pratiquement rien. Benartzi et Thaler soutenaient que les investisseurs qui évaluent fréquemment leurs avoirs exigent une prime plus élevée pour la même volatilité, ce qui fait du premier un détenteur d’actions plus prudent que le second, même si les deux possèdent le même indice.</p>
<h2>Une décision de taux qui déplace sans cesse le point de référence</h2>
<p>Daniel Kahneman et Amos Tversky ont montré, dans leur article de 1979 sur la théorie des perspectives publié dans Econometrica, que les gens jugent les résultats comme des gains ou des pertes par rapport à un point de référence, et non comme une richesse finale. En octobre, le point de référence a été le prix que le marché attribue à la décision de la Banque du Canada du 28 octobre, et il a fortement oscillé.</p>
<p>Selon des données de LSEG rapportées par Reuters, la probabilité d’une hausse d’un quart de point s’établissait à environ 25&nbsp;% le 9 octobre, après que l’Enquête sur la population active a fait état d’une perte nette de 68&nbsp;300 emplois en septembre. Le 20 octobre, la tarification des swaps citée par Elias Haddad, stratège chez Brown Brothers Harriman, plaçait cette probabilité près de 78&nbsp;%, après que le gouverneur Tiff Macklem a prévenu, le 16 octobre, que le risque d’une inflation plus large et plus persistante avait augmenté.</p>
<p>Les économistes n’ont pas autant changé d’avis. Cinq économistes de Bay Street interrogés par Canadian Mortgage Professional s’attendaient à un statu quo au 9 octobre, et l’économiste Abbey Xu, de RBC, prévoit que le taux directeur restera à 2,25&nbsp;% jusqu’à la fin de 2026. L’IPC de septembre, publié le 19 octobre, s’est établi à 3,1&nbsp;% contre une prévision de 3,2&nbsp;% dans un sondage de Reuters. Lorsque le marché et les prévisionnistes sont aussi éloignés, un maintien du taux le 28 octobre sera une surprise pour un camp et une confirmation pour l’autre, et la réaction dépendra de l’ancrage que chaque investisseur portait déjà.</p>
<h2>Prudence affichée et comportement réel sont deux choses différentes</h2>
<p>L’AAII a aussi demandé à ses membres s’ils avaient modifié leur approche de placement et, le cas échéant, comment. Ainsi, 35,3&nbsp;% ont dit être devenus légèrement plus conservateurs et 6,6&nbsp;% beaucoup plus conservateurs, pour un total de 41,9&nbsp;%. Seulement 4,9&nbsp;% ont dit être devenus plus agressifs. Par ailleurs, 32,0&nbsp;% n’ont signalé aucun changement et 21,3&nbsp;% seulement des changements modestes.</p>
<p>Le groupe à surveiller est celui des 35,3&nbsp;%. Devenir légèrement plus conservateur n’est pas une vente. C’est une pondération en actions réduite, un solde de liquidités plus élevé ou une cotisation reportée, chacun défendable le jour où il survient. Brad Barber et Terrance Odean ont montré, dans une étude de 2000 parue dans le Journal of Finance et portant sur environ 66&nbsp;000 ménages américains, que les ménages qui négociaient le plus ont obtenu 11,4&nbsp;% par an contre 17,9&nbsp;% pour le marché de 1991 à 1996, ce qui documente le coût d’agir sous l’effet d’un inconfort à court terme.</p>
<p>Rien dans l’anxiété d’octobre n’est irrationnel. Les probabilités de hausse ont bougé de plus de 50 points en 11 jours, et le TSX a changé de direction 12 fois en 24 variations quotidiennes. Le risque comportemental tient à ce que des réactions fréquentes, d’apparence raisonnable, à un signal bruité s’additionnent pour donner un portefeuille qui ne correspond plus au plan pour lequel il a été conçu.</p>',
  '<div class="toolkit-section">
<div class="toolkit-section-label">Ce qu’ils ressentent</div>
<p>Les clients dont le portefeuille est équilibré perçoivent l’aller-retour du TSX comme une perte jamais entièrement effacée, parce que le creux du 7 octobre reste vif dans les esprits, même si l’indice a clôturé le 21 octobre à moins de 10,62 points de son niveau du 22 septembre. Les clients qui ont une hypothèque ou une marge de crédit à taux variable ont les yeux rivés sur le 28 octobre et se préparent à une hausse. Les retraités qui tirent un revenu de leur portefeuille ressentent chaque oscillation personnellement et sont tentés de détenir plus de liquidités que leur plan ne le prévoit.</p>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Quoi dire</div>
<div class="script-box">Merci d’avoir pris l’appel. Je veux vous donner le portrait réel, parce que les trois dernières semaines ont semblé plus rudes que ne le disent les chiffres. Le TSX a reculé d’environ 3,6&nbsp;% entre le 22 septembre et le 7 octobre, puis a regagné environ 3,7&nbsp;% d’ici le 21 octobre&nbsp;; il se trouve donc presque exactement là où il était il y a un mois. Ce qui a changé, c’est la fréquence à laquelle on nous sert une nouvelle manchette. La probabilité d’une hausse de la Banque du Canada est passée d’environ une sur quatre à environ trois sur quatre en moins de deux semaines, et la décision tombe le 28 octobre. Quelle que soit l’issue, votre plan a été conçu pour traverser une décision de taux, et rien n’y dépend d’une devinette sur celle-ci. Ce que je propose, c’est de confirmer que vos besoins de liquidités et de revenu pour les 12 prochains mois sont couverts, afin que vous puissiez regarder au-delà des manchettes. Si quoi que ce soit a changé dans votre situation, dites-le-moi maintenant et nous ajusterons le plan délibérément plutôt qu’un mauvais jour. Pouvons-nous prévoir un court appel la semaine suivant la décision&nbsp;?</div>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Qui est touché</div>
<p><strong>Forte incidence&nbsp;:</strong> les clients qui ont une hypothèque, une marge de crédit sur valeur domiciliaire ou une marge de crédit d’entreprise à taux variable, dont le coût d’emprunt réagit directement à la décision du 28 octobre, et les retraités en phase de décaissement qui détiennent en liquidités moins de 12 mois de retraits.</p>
<p><strong>Incidence variable&nbsp;:</strong> les clients dont le portefeuille est équilibré, qui ont traversé un repli de 3,6&nbsp;% et un rebond de 3,7&nbsp;%, mais qui ont peut-être suspendu leurs cotisations ou allégé leurs actions entre-temps.</p>
<p><strong>Avantage potentiel&nbsp;:</strong> les clients dont des CPG arrivent à échéance ou qui détiennent des liquidités, et qui réinvestiraient à des taux plus élevés si la Banque du Canada relève son taux directeur de 2,25&nbsp;%.</p>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Liste de vérification</div>
<div class="checklist-item">Dresser la liste des clients ayant une dette à taux variable et noter les dates de renouvellement avant le 28 octobre.</div>
<div class="checklist-item">Confirmer que les retraités en phase de décaissement détiennent 12 mois de retraits en liquidités ou en placements à court terme.</div>
<div class="checklist-item">Repérer les clients qui ont suspendu leurs cotisations ou se sont réfugiés dans les liquidités depuis le 1er octobre et les signaler pour un appel.</div>
<div class="checklist-item">Planifier des appels de suivi pour la semaine du 2 novembre, après la décision de taux et avant le budget fédéral du 5 novembre.</div>
<div class="checklist-item">Consigner chaque conversation et tout changement déclaré de tolérance au risque dans le dossier du client.</div>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Modèle de courriel de suivi</div>
<div class="email-box" id="respond-email">
<strong>Objet&nbsp;:</strong> Où en sont les choses avant le 28 octobre<br><br>
Bonjour [Nom du client],<br><br>
Merci de notre conversation d’aujourd’hui. En résumé&nbsp;: le TSX a reculé d’environ 3,6&nbsp;% du 22 septembre au 7 octobre et a regagné environ 3,7&nbsp;% d’ici le 21 octobre&nbsp;; il se situe donc près de son point de départ. La Banque du Canada annonce sa décision de taux le 28 octobre, et les attentes du marché ont changé plusieurs fois depuis deux semaines.<br><br>
Votre plan ne dépend pas d’une prévision de cette décision. Je vais passer en revue vos besoins de liquidités et de revenu pour les 12 prochains mois et confirmer qu’ils sont couverts. Si votre situation a changé, dites-le-moi et nous ajusterons le plan délibérément.<br><br>
Je propose que nous nous parlions de nouveau la semaine du 2 novembre. Dites-moi quelle journée vous convient.<br><br>
[Votre nom]<br><br>
<em>La présente communication est fournie à des fins éducatives seulement et ne constitue pas un conseil en placement personnalisé.</em>
</div>
<button class="btn-copy" onclick="copyEmail(''respond-email'', this)">Copier le courriel</button>
</div>',
  '<div class="toolkit-section">
<div class="toolkit-section-label">Profils de clients à cibler</div>
<p><strong>Investisseurs autonomes qui consultent leur solde chaque jour&nbsp;:</strong> un marché qui a changé de direction 12 fois en 24 séances donne aux investisseurs autonomes plus de raisons d’agir, sans personne pour mettre leur décision à l’épreuve.</p>
<p><strong>Emprunteurs à taux variable&nbsp;:</strong> les ménages ayant une hypothèque ou une marge de crédit à taux variable suivent de près le 28 octobre et ont une question concrète à poser.</p>
<p><strong>Investisseurs autonomes récemment retraités&nbsp;:</strong> les personnes qui tirent un revenu de leurs propres comptes pour la première fois ressentent les replis plus vivement que ceux qui accumulent.</p>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Phrase d’accroche</div>
<div class="script-box">Je vous appelle parce que la décision de la Banque du Canada du 28 octobre divise le marché, et plusieurs investisseurs autonomes m’ont dit consulter leurs comptes beaucoup plus souvent qu’ils ne le voudraient.</div>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Proposition de valeur</div>
<p>Le dernier mois a ouvert une fenêtre de prospection parce que le flux d’information était bruyant et contradictoire. Les probabilités de hausse de taux sont passées d’environ 25&nbsp;% à près de 78&nbsp;% en 11 jours, alors que le TSX a terminé à moins de 10,62 points de son point de départ. Un investisseur qui gère seul n’a pas de cadre pour distinguer ce bruit d’un changement qui compte.</p>
<p>Le conseiller propose un plan rédigé avant la manchette, un calendrier de révision fixe et un second regard sur toute décision de se réfugier dans les liquidités. La valeur ne tient pas à une prévision du 28 octobre. Elle tient à un processus qui n’en a pas besoin.</p>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Questions de découverte</div>
<p>1. À quelle fréquence consultez-vous vos comptes en ce moment, comparativement à il y a un an&nbsp;?</p>
<p>2. Avez-vous modifié quoi que ce soit dans votre portefeuille depuis le début d’octobre, même une petite chose&nbsp;?</p>
<p>3. Avez-vous une dette à taux variable, et quand doit-elle être renouvelée&nbsp;?</p>
<p>4. Si le marché reculait de 5&nbsp;% de plus la semaine prochaine, que feriez-vous, et à qui en parleriez-vous d’abord&nbsp;?</p>
<p>5. Suivez-vous un plan écrit, ou décidez-vous semaine après semaine&nbsp;?</p>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Modèle de courriel de prospection</div>
<div class="email-box" id="prospect-email">
<strong>Objet&nbsp;:</strong> Une façon plus sereine d’aborder le 28 octobre<br><br>
Bonjour [Nom du prospect],<br><br>
La décision de la Banque du Canada du 28 octobre a fait bouger sensiblement les attentes du marché en deux semaines, et le TSX a varié de plus de 1&nbsp;% à six reprises depuis la mi-septembre. Bien des investisseurs autonomes me disent remettre en question des positions qu’ils détenaient sereinement il y a un mois.<br><br>
J’aide les investisseurs à bâtir un plan qui tient le coup lors d’événements comme celui-ci. Si cela peut vous être utile, je vous offre volontiers une conversation de 20 minutes, sans engagement, sur la façon dont cela fonctionne.<br><br>
Un court appel la semaine prochaine vous conviendrait-il&nbsp;?<br><br>
[Votre nom]<br><br>
<em>La présente communication est fournie à des fins éducatives seulement et ne constitue pas un conseil en placement personnalisé.</em>
</div>
<button class="btn-copy" onclick="copyEmail(''prospect-email'', this)">Copier le courriel</button>
</div>',
