INSERT OR REPLACE INTO articles
  (slug, desk, article_type, title, dek, brief_html, body_html, respond_html, prospect_html, key_numbers, hero_image, hero_caption, read_time, published_at, tags, toolkit_gated, sources_text, en_slug)
VALUES (
  '2026/10/23/la-fenetre-fiscale-de-fin-dannee-precede-le-budget-du-5-novembre',
  'tax',
  'article',
  'La fenêtre fiscale de fin d’année précède le budget du 5 novembre',
  'Aucune mesure fiscale pour particuliers n’est confirmée au budget ; le 30 déc., le 1er mars et un taux d’inclusion de 50 % servent de repères.',
  '<ul>
<li><strong>Aucune mesure fiscale pour les particuliers n’est confirmée le 5 novembre,</strong><span> la planification doit donc reposer sur les règles en vigueur.</span></li>
<li><strong>Le taux d’inclusion des gains en capital demeure à 50&nbsp;%,</strong><span> après l’annulation de la proposition des deux tiers en mars 2025.</span></li>
<li><strong>Le 30 décembre est la dernière date de transaction réglée en 2026,</strong><span> pour les gains ou pertes dans les comptes non enregistrés.</span></li>
<li><strong>La date limite du REER 2026 est le 1er mars 2027,</strong><span> avec un plafond de 33&nbsp;810&nbsp;$.</span></li>
<li><strong>La règle de la perte apparente s’applique aux rachats dans un REER ou un CELI,</strong><span> et une perte refusée ne peut être récupérée.</span></li>
</ul>',
  '<p>Le budget fédéral sera déposé le 5 novembre, et aucune mesure fiscale visant les particuliers n’a été confirmée d’ici là. Le ministre des Finances, François-Philippe Champagne, le dépose alors que le directeur parlementaire du budget prévoit un solde de fonctionnement équilibré en 2028-2029, un an plus tard que promis, et après une mise à jour printanière qui montrait un déficit de 65,3 milliards de dollars. Ce contexte ne prédit pas de changement fiscal. Il signifie toutefois que les clients doivent planifier selon les règles en vigueur aujourd’hui.</p>
<h2>Les règles qui sont fixées avant le 5 novembre</h2>
<p>Le taux d’inclusion des gains en capital est de 50&nbsp;% pour les particuliers, les sociétés et les fiducies. La hausse proposée à deux tiers a été annulée le 21 mars 2025, et rien de ce qui a été annoncé depuis ne la rétablit. Pour 2026, le plafond de cotisation au REER est de 33&nbsp;810&nbsp;$, le plafond annuel du CELI est de 7&nbsp;000&nbsp;$, et le CELIAPP permet 8&nbsp;000&nbsp;$ par année jusqu’à un maximum cumulatif de 40&nbsp;000&nbsp;$.</p>
<p>La date limite du REER pour une déduction 2026 est le 1er mars 2027. Cette date est le 60e jour de l’année, et elle tombe un lundi.</p>
<p>Le plafond du REER augmente chaque année depuis 2020, passant de 27&nbsp;230&nbsp;$ à 33&nbsp;810&nbsp;$.</p>
<div class="hdq-chart">
<div style="background:#ffffff;border:1px solid #d0d0d0;width:100%;font-family:-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif;">
<div style="background:#f5f5f5;border-bottom:1px solid #d0d0d0;padding:10px 14px;display:flex;align-items:baseline;gap:16px;flex-wrap:wrap;">
<span style="font-size:13px;font-weight:700;color:#111;letter-spacing:0.02em;">PLAFOND DE COTISATION AU REER&nbsp;: MAXIMUM ANNUEL</span>
<span style="font-size:20px;font-weight:700;color:#111;">33&nbsp;810&nbsp;$</span>
<span style="font-size:13px;color:#2e7d32;">&#9650; 4,1&nbsp;%</span>
<span style="font-size:11px;color:#888;margin-left:auto;">ANNUEL &nbsp;|&nbsp; 2020 À 2026</span>
</div>
<div style="padding:12px 14px 8px;">
<script>
(function(){
  var _cs = document.currentScript;
  var svg = document.createElementNS("http://www.w3.org/2000/svg","svg");
  svg.setAttribute("viewBox","0 0 680 300");
  svg.setAttribute("width","100%");
  var FONT = "-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif";
  function el(tag, attrs, txt){ var e = document.createElementNS("http://www.w3.org/2000/svg", tag); for (var k in attrs) e.setAttribute(k, attrs[k]); if (txt !== undefined) e.textContent = txt; return e; }
  function tx(s, a){ a["font-family"] = FONT; return el("text", a, s); }
  function fmt(v, d){ var p = v.toFixed(d).split("."); p[0] = p[0].replace(/\B(?=(\d{3})+(?!\d))/g, " "); return p.join(","); }
  var CFG = {"data":[27230,27830,29210,30780,31560,32490,33810],"labels":["2020","2021","2022","2023","2024","2025","2026"],"lblIdx":[0,1,2,3,4,5,6],"bands":[],"refs":[],"events":[],"pill":"33 810","step":1000,"dig":0,"gap":12};
  var data = CFG.data;
  var margin = {left: 62, right: 24, top: 18, bottom: 46};
  var PW = 680 - margin.left - margin.right;
  var PH = 300 - margin.top - margin.bottom;
  var MT = margin.top;
  var n = data.length;
  var vmin = Math.min.apply(null, data), vmax = Math.max.apply(null, data);
  var pad = (vmax - vmin) * 0.12;
  var ymin = Math.floor((vmin - pad) / CFG.step) * CFG.step;
  var ymax = Math.ceil((vmax + pad) / CFG.step) * CFG.step;
  function xp(i){ return margin.left + (i / (n - 1)) * PW; }
  function yp(v){ return MT + PH - ((v - ymin) / (ymax - ymin)) * PH; }
  var lastX = xp(n - 1), lastY = yp(data[n - 1]);
  var currentVal = data[n - 1];
  var labelsLayer = [];

  CFG.bands.forEach(function(b){
    var x1 = xp(b.from), x2 = xp(b.to);
    svg.appendChild(el("rect", {x: x1, y: MT, width: x2 - x1, height: PH, fill: b.color, "fill-opacity": b.op}));
    labelsLayer.push(tx(b.label, {x: (x1 + x2) / 2, y: MT + 8, "text-anchor": "middle", "font-size": 7, "font-weight": 700, fill: b.color}));
  });

  var t, yTicks = [];
  for (t = ymin; t <= ymax; t += CFG.step) { if (Math.abs(t - currentVal) > CFG.step * 0.2) yTicks.push(t); }
  yTicks.forEach(function(v){
    svg.appendChild(el("line", {x1: margin.left, x2: margin.left + PW, y1: yp(v), y2: yp(v), stroke: "#ececec", "stroke-width": 0.5}));
    labelsLayer.push(tx(fmt(v, 0), {x: margin.left - 6, y: yp(v) + 3, "text-anchor": "end", "font-size": 8.5, fill: "#aaaaaa"}));
  });

  var refYs = [];
  CFG.refs.forEach(function(r){
    var ry = yp(r.v);
    refYs.push(ry);
    svg.appendChild(el("line", {x1: margin.left, x2: margin.left + PW, y1: ry, y2: ry, stroke: r.color, "stroke-width": 1, "stroke-dasharray": "3,3"}));
    if (Math.abs(r.v - currentVal) / currentVal >= 0.03) {
      labelsLayer.push(tx(r.label, {x: margin.left + 10, y: ry - 10, "text-anchor": "start", "font-size": 7, "font-weight": 700, fill: r.color}));
    }
  });

  var d = "";
  data.forEach(function(v, i){ d += (i === 0 ? "M" : "L") + xp(i).toFixed(2) + " " + yp(v).toFixed(2) + " "; });
  svg.appendChild(el("path", {d: d, fill: "none", stroke: "#4a5568", "stroke-width": 1.6, "stroke-linejoin": "round"}));

  svg.appendChild(el("line", {x1: margin.left, x2: margin.left, y1: MT, y2: MT + PH, stroke: "#d8d8d8", "stroke-width": 1}));
  svg.appendChild(el("line", {x1: margin.left, x2: margin.left + PW, y1: MT + PH, y2: MT + PH, stroke: "#d8d8d8", "stroke-width": 1}));

  CFG.lblIdx.forEach(function(i, k){
    var anchor = (i === 0) ? "start" : (i === n - 1 ? "end" : "middle");
    labelsLayer.push(tx(CFG.labels[i], {x: xp(i), y: MT + PH + 14, "text-anchor": anchor, "font-size": 8, fill: "#999999"}));
  });

  var floorY = refYs.length ? Math.min.apply(null, refYs) - CFG.gap : MT + PH - CFG.gap;
  CFG.events.forEach(function(ev){
    var ex = xp(ev.i);
    svg.appendChild(el("line", {x1: ex, x2: ex, y1: MT, y2: MT + PH, stroke: "#1a3560", "stroke-opacity": 0.5, "stroke-width": 1, "stroke-dasharray": "2,3"}));
    var crowded = CFG.events.some(function(o){ return o.i !== ev.i && Math.abs(xp(o.i) - ex) < 85; });
    var longest = 0;
    ev.lines.forEach(function(l){ longest = Math.max(longest, Math.ceil(l.length * 7 * 0.68)); });
    var nearRight = (ex + longest + 3) > (margin.left + PW);
    var anchor = (crowded || nearRight) ? "end" : "start";
    var lx = (anchor === "end") ? ex - 3 : ex + 3;
    var yStart = floorY - (ev.lines.length - 1) * 9 - (crowded ? 30 : 0);
    ev.lines.forEach(function(l, k){
      labelsLayer.push(tx(l, {x: lx, y: yStart + k * 9, "text-anchor": anchor, "font-size": 7, "font-weight": 700, fill: "#1a3560"}));
    });
  });

  svg.appendChild(el("circle", {cx: lastX, cy: lastY, r: 4, fill: "#4a5568"}));

  var pillText = CFG.pill;
  var pillW = Math.ceil(pillText.length * 9 * 0.58) + 10;
  var pillH = 16;
  var pillX = lastX - pillW - 6;
  var pillY = lastY - pillH / 2;
  if (pillX < margin.left) pillX = margin.left;
  svg.appendChild(el("rect", {x: pillX, y: pillY, width: pillW, height: pillH, rx: 3, fill: "#e8a825"}));
  svg.appendChild(tx(pillText, {x: pillX + pillW / 2, y: pillY + pillH / 2 + 3.5, "text-anchor": "middle", "font-size": 9, "font-weight": 700, fill: "#111111"}));

  labelsLayer.forEach(function(e){ svg.appendChild(e); });
  _cs.parentNode.appendChild(svg);
})();
</script>
</div>
<div style="font-family:-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif;font-size:10px;color:#999;padding:4px 14px 10px;font-style:italic;">Source&nbsp;: Agence du revenu du Canada, plafonds annuels de cotisation au REER, 2020 à 2026. &nbsp;|&nbsp; hdq.ca</div>
</div>
</div>
<p style="font-size:11px;color:#666;font-family:-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif;margin-top:6px;">Le plafond de 2026, soit 33&nbsp;810&nbsp;$, dépasse de 24,2&nbsp;% celui de 2020, soit 27&nbsp;230&nbsp;$. La hausse de 2026 par rapport à 2025 est de 4,1&nbsp;%. Les droits de cotisation correspondent à 18&nbsp;% du revenu gagné de l’année précédente, jusqu’à concurrence du plafond.</p>
<p>Une cotisation au REER est un report d’impôt, et elle compte surtout pour les clients dont le taux marginal de 2026 dépasse celui qu’ils prévoient à la retraite. Une cotisation au CELI ne donne droit à aucune déduction, et les retraits n’ont pas d’incidence sur les prestations fondées sur le revenu. Ces deux comptes répondent à des questions différentes&nbsp;; le choix doit donc suivre le client, et non le calendrier.</p>
<h2>La date de transaction du 30 décembre pour les gains et les pertes</h2>
<p>Une vente compte en 2026 seulement si elle est réglée en 2026. Avec le règlement T+1, la dernière date de transaction qui se règle d’ici le 31 décembre est le mercredi 30 décembre. Les clients qui veulent réaliser un gain ou une perte dans un compte non enregistré cette année doivent avoir passé l’ordre d’ici là.</p>
<p>L’indice composé S&amp;P/TSX a clôturé le 21 octobre à moins de 10,62 points de son niveau du 22 septembre. Cela ne dit rien des positions individuelles. Un compte non enregistré peut contenir de gros gains et de grosses pertes en même temps, et un indice stable masque les deux. Les pertes en capital sont appliquées aux gains de la même année, reportées rétroactivement sur trois ans ou reportées indéfiniment.</p>
<p>La règle de la perte apparente refuse une perte si le client ou une personne affiliée, y compris un conjoint ou une société qu’il contrôle, achète le même bien ou un bien identique dans les 30 jours précédant ou suivant la vente et le détient toujours à la fin de cette période. Un rachat dans un REER ou un CELI entraîne le refus, et la perte ne peut être récupérée.</p>
<h2>Le pont de planification selon le type de client</h2>
<p><strong>Les retraités non incorporés</strong> qui ont de gros gains non enregistrés peuvent réaliser des gains une année où leur revenu est plus faible, puis reconstituer la position dans un CELI selon les droits disponibles. <strong>Les propriétaires d’entreprise incorporés</strong> détiennent des placements dans un compte de société, où la question de planification porte sur le revenu passif et le dosage des pertes et des gains en fin d’année, et non sur le plafond du REER.</p>
<p><strong>Les clients sans CELIAPP</strong> qui sont admissibles comme premiers acheteurs d’une propriété n’accumulent des droits qu’à partir de l’année d’ouverture du compte. Un compte ouvert avant le 31 décembre fait démarrer le compteur pour 2026. Comme le budget du 5 novembre pourrait changer quelque chose, la démarche pratique consiste à planifier la revue de fin d’année pour la semaine du 9 novembre, après la lecture du budget.</p>',
  '<div class="toolkit-section">
<div class="toolkit-section-label">Ce qu’ils ressentent</div>
<p>Les clients suivent le budget du 5 novembre et se demandent s’ils doivent agir d’abord ou attendre. Les propriétaires d’entreprise s’inquiètent des règles applicables aux comptes de société. Les clients qui ont de gros gains dans des comptes non enregistrés craignent un taux d’inclusion plus élevé, même si la hausse a été annulée. Les retraités veulent savoir si les mouvements de fin d’année feront passer leur revenu dans une tranche supérieure.</p>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Quoi dire</div>
<div class="script-box">Merci de m’accorder du temps. Le budget fédéral sera déposé le 5 novembre, et rien n’a été confirmé à l’avance en matière d’impôt des particuliers&nbsp;; je planifie donc selon les règles actuelles. Le taux d’inclusion des gains en capital est de 50&nbsp;%. La hausse aux deux tiers a été annulée en mars 2025. Avant la fin de l’année, je veux passer en revue vos gains et pertes dans votre compte non enregistré, vérifier vos droits de cotisation au REER et au CELI, et m’assurer que toute transaction est passée d’ici le 30 décembre pour être réglée en 2026. Si le budget change quelque chose, nous ajusterons. Pouvons-nous réserver une heure la semaine du 9 novembre&nbsp;?</div>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Qui est touché</div>
<p><strong>Forte incidence&nbsp;:</strong> les clients qui ont des comptes non enregistrés contenant à la fois des gains et des pertes, et les propriétaires d’entreprise incorporés qui ont des comptes de placement de société.</p>
<p><strong>Incidence variable&nbsp;:</strong> les détenteurs de REER qui hésitent entre une déduction immédiate et des droits de CELI, selon leur taux d’imposition prévu à la retraite.</p>
<p><strong>Avantage potentiel&nbsp;:</strong> les premiers acheteurs d’une propriété qui n’ont pas encore ouvert de CELIAPP et veulent que les droits de 2026 commencent à s’accumuler.</p>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Liste de vérification</div>
<div class="checklist-item">Dresser la liste des clients non enregistrés ayant des pertes et des gains, réalisés ou latents, et signaler la date de transaction du 30 décembre.</div>
<div class="checklist-item">Vérifier chaque ménage pour des rachats dans la période de 30 jours, y compris dans les comptes du conjoint et des sociétés.</div>
<div class="checklist-item">Confirmer les droits de REER, de CELI et de CELIAPP pour 2026 ainsi que la date limite du REER, le 1er mars 2027.</div>
<div class="checklist-item">Repérer les premiers acheteurs sans CELIAPP et planifier une conversation avant le 31 décembre.</div>
<div class="checklist-item">Planifier les revues de fin d’année pour la semaine du 9 novembre, après le budget fédéral.</div>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Modèle de courriel de suivi</div>
<div class="email-box" id="respond-email">
<strong>Objet&nbsp;:</strong> Revue fiscale de fin d’année et dates clés<br><br>
Bonjour [Nom du client],<br><br>
Merci de notre conversation. Le budget fédéral sera déposé le 5 novembre, et aucune mesure fiscale visant les particuliers n’a été confirmée à l’avance&nbsp;; je planifie donc selon les règles actuelles. Le taux d’inclusion des gains en capital demeure à 50&nbsp;%.<br><br>
Trois dates à retenir&nbsp;: la dernière date de transaction réglée en 2026 est le 30 décembre, votre date limite de cotisation au REER pour la déduction de 2026 est le 1er mars 2027, et tout CELIAPP devrait être ouvert avant le 31 décembre pour commencer à accumuler les droits de 2026.<br><br>
Je propose une revue de fin d’année la semaine du 9 novembre. Dites-moi quelle journée vous convient.<br><br>
[Votre nom]<br><br>
<em>La présente communication est fournie à des fins éducatives seulement et ne constitue pas un conseil fiscal ou de placement personnalisé.</em>
</div>
<button class="btn-copy" onclick="copyEmail(''respond-email'', this)">Copier le courriel</button>
</div>',
  '<div class="toolkit-section">
<div class="toolkit-section-label">Profils de clients à cibler</div>
<p><strong>Investisseurs autonomes ayant des comptes non enregistrés&nbsp;:</strong> ils détiennent des gains et des pertes en même temps et planifient rarement en fonction de la date de transaction du 30 décembre.</p>
<p><strong>Propriétaires d’entreprise incorporés&nbsp;:</strong> ils détiennent des placements passifs dans une société et ont besoin d’une planification de fin d’année adaptée au compte de société.</p>
<p><strong>Premiers acheteurs d’une propriété&nbsp;:</strong> un CELIAPP ouvert en 2026 commence à accumuler des droits cette année.</p>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Phrase d’accroche</div>
<div class="script-box">Je vous appelle parce que la dernière date de transaction réglée en 2026 est le 30 décembre, et bien des investisseurs autonomes n’ont pas examiné leurs gains et leurs pertes en tenant compte de cette date.</div>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Proposition de valeur</div>
<p>La fin d’année suit un calendrier fixe et des règles fixes&nbsp;: un taux d’inclusion de 50&nbsp;%, une fenêtre de 30 jours pour la perte apparente et une date limite du REER au 1er mars 2027. Un investisseur qui gère seul l’apprend souvent après coup.</p>
<p>Le conseiller propose une revue à l’échelle du ménage qui couvre tous les comptes, le conjoint et la société ensemble, là où se produisent les erreurs de perte apparente.</p>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Questions de découverte</div>
<p>1. Détenez-vous des placements hors d’un REER ou d’un CELI, et certains affichent-ils une perte&nbsp;?</p>
<p>2. Avez-vous vendu puis racheté le même titre au cours des 30 derniers jours, dans un compte quelconque&nbsp;?</p>
<p>3. Combien de droits de REER et de CELI inutilisés avez-vous pour 2026&nbsp;?</p>
<p>4. Vous-même ou votre conjoint possédez-vous une société qui détient des placements&nbsp;?</p>
<p>5. Prévoyez-vous acheter votre première propriété, et avez-vous ouvert un CELIAPP&nbsp;?</p>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Modèle de courriel de prospection</div>
<div class="email-box" id="prospect-email">
<strong>Objet&nbsp;:</strong> Trois dates fiscales avant la fin de l’année<br><br>
Bonjour [Nom du prospect],<br><br>
Avec le budget fédéral attendu le 5 novembre, bien des investisseurs attendent avant d’agir. Trois dates n’en dépendent pas&nbsp;: le 30 décembre est la dernière date de transaction réglée en 2026, le 31 décembre est la date limite pour ouvrir un CELIAPP et obtenir les droits de 2026, et le 1er mars 2027 est la date limite du REER pour la déduction de 2026.<br><br>
Si cela peut vous être utile, je vous offre volontiers une conversation de 20 minutes, sans engagement, sur la façon dont ces dates s’appliquent à vos comptes.<br><br>
Un court appel la semaine prochaine vous conviendrait-il&nbsp;?<br><br>
[Votre nom]<br><br>
<em>La présente communication est fournie à des fins éducatives seulement et ne constitue pas un conseil fiscal ou de placement personnalisé.</em>
</div>
<button class="btn-copy" onclick="copyEmail(''prospect-email'', this)">Copier le courriel</button>
</div>',
  '[{"value":"33 810 $","label":"Plafond du REER 2026"},{"value":"50 %","label":"Taux d’inclusion, gains en capital"},{"value":"30 déc.","label":"Dernière date de transaction 2026"},{"value":"1er mars","label":"Date limite REER 2026"}]',
  'tax-140.jpg',
  'La planification de fin d’année pour les comptes enregistrés et non enregistrés commence bien avant le dépôt du budget fédéral le 5 novembre. Photo : iStock.',
  4,
  '2026-10-23T09:00:00',
