INSERT OR REPLACE INTO articles
  (slug, desk, article_type, title, dek, brief_html, body_html, respond_html, prospect_html, key_numbers, hero_image, hero_caption, read_time, published_at, tags, toolkit_gated, sources_text, en_slug)
VALUES (
  '2026/10/23/inflation-globale-a-3-1-pour-cent-mais-les-mesures-fondamentales-prisees-de-la-banque-sont-sous-2-pour-cent',
  'economy',
  'article',
  'Inflation globale à 3,1 %, mais les mesures fondamentales prisées de la Banque sont sous 2 %',
  'L’écart entre l’IPC global et l’IPC-tronq est passé de moins 0,5 point en février à 1,3 point en septembre, et la décision du 28 octobre dépend de sa résorption.',
  '<ul>
<li><strong>L’IPC global était de 3,1&nbsp;% en septembre,</strong><span> contre 3,2&nbsp;% attendu et 3,0&nbsp;% en août.</span></li>
<li><strong>Les mesures fondamentales privilégiées sont sous 2&nbsp;%,</strong><span> avec l’IPC-tronq à 1,8&nbsp;% et l’IPC-méd à 1,9&nbsp;%.</span></li>
<li><strong>Le carburant explique l’écart,</strong><span> l’essence ayant augmenté de 27,8&nbsp;% et les prix hors essence de 2,2&nbsp;%.</span></li>
<li><strong>Les swaps tarifent une hausse à environ 78&nbsp;%,</strong><span> alors que les économistes sondés s’attendent à un maintien à 2,25&nbsp;% le 28 octobre.</span></li>
<li><strong>Le prochain rapport sur l’IPC, le 16 novembre, est le test,</strong><span> pour savoir si le choc énergétique s’étend.</span></li>
</ul>',
  '<p>Les prix à la consommation au Canada ont augmenté de 3,1&nbsp;% en septembre par rapport à un an plus tôt, un chiffre qui arrive neuf jours avant que la Banque du Canada décide, le 28 octobre, de relever ou non un taux directeur qui se situe à 2,25&nbsp;%. L’inflation globale dépasse le plafond de 3&nbsp;% de la fourchette cible de la Banque. Les deux mesures fondamentales que la Banque privilégie, l’IPC-tronq à 1,8&nbsp;% et l’IPC-méd à 1,9&nbsp;%, sont toutes deux inférieures à la cible de 2&nbsp;%. Les deux constats sont exacts, et la décision dépend de celui que la Banque croit appelé à persister.</p>
<h2>Ce que disent réellement les mesures fondamentales</h2>
<p>Le rapport de septembre, publié le 19 octobre, s’est établi 0,1 point sous la prévision de 3,2&nbsp;% d’un sondage de Reuters. En août, l’IPC était de 3,0&nbsp;%. La variation mensuelle a été de 0,1&nbsp;%, contre 0,2&nbsp;% attendu. L’IPC-tronq a reculé à 1,8&nbsp;% contre 1,9&nbsp;%, l’IPC-méd à 1,9&nbsp;% contre 2,0&nbsp;%, et l’IPC-comm à 2,4&nbsp;% contre 2,6&nbsp;%.</p>
<p>L’écart entre l’IPC global et l’IPC-tronq montre à quel point le carburant a éloigné les deux mesures. En février, l’inflation globale se situait 0,5 point sous l’IPC-tronq. En septembre, elle se situait 1,3 point au-dessus, la lecture la plus large de la série.</p>
<div class="hdq-chart">
<div style="background:#ffffff;border:1px solid #d0d0d0;width:100%;font-family:-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif;">
<div style="background:#f5f5f5;border-bottom:1px solid #d0d0d0;padding:10px 14px;display:flex;align-items:baseline;gap:16px;flex-wrap:wrap;">
<span style="font-size:13px;font-weight:700;color:#111;letter-spacing:0.02em;">IPC GLOBAL MOINS IPC-TRONQ (POINTS DE POURCENTAGE)</span>
<span style="font-size:20px;font-weight:700;color:#111;">1,3&nbsp;pt</span>
<span style="font-size:13px;color:#2e7d32;">&#9650; 0,2&nbsp;pt</span>
<span style="font-size:11px;color:#888;margin-left:auto;">MENSUEL &nbsp;|&nbsp; FÉVR. À SEPT. 2026</span>
</div>
<div style="padding:12px 14px 8px;">
<script>
(function(){
  var _cs = document.currentScript;
  var svg = document.createElementNS("http://www.w3.org/2000/svg","svg");
  svg.setAttribute("viewBox","0 0 680 300");
  svg.setAttribute("width","100%");
  var FONT = "-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif";
  function el(tag, attrs, txt){ var e = document.createElementNS("http://www.w3.org/2000/svg", tag); for (var k in attrs) e.setAttribute(k, attrs[k]); if (txt !== undefined) e.textContent = txt; return e; }
  function tx(s, a){ a["font-family"] = FONT; return el("text", a, s); }
  function fmt(v, d){ var p = v.toFixed(d).split("."); p[0] = p[0].replace(/\B(?=(\d{3})+(?!\d))/g, " "); return p.join(","); }
  var CFG = {"data":[-0.5,0.2,0.8,1.2,0.9,1.1,1.1,1.3],"labels":["févr.","mars","avr.","mai","juin","juill.","août","sept."],"lblIdx":[0,1,2,3,4,5,6,7],"bands":[],"refs":[{"v":0.0,"color":"#7a3030","label":"IPC GLOBAL = IPC-TRONQ"}],"events":[],"pill":"1,3","step":0.5,"dig":1,"gap":12};
  var data = CFG.data;
  var margin = {left: 62, right: 24, top: 18, bottom: 46};
  var PW = 680 - margin.left - margin.right;
  var PH = 300 - margin.top - margin.bottom;
  var MT = margin.top;
  var n = data.length;
  var vmin = Math.min.apply(null, data), vmax = Math.max.apply(null, data);
  var pad = (vmax - vmin) * 0.12;
  var ymin = Math.floor((vmin - pad) / CFG.step) * CFG.step;
  var ymax = Math.ceil((vmax + pad) / CFG.step) * CFG.step;
  function xp(i){ return margin.left + (i / (n - 1)) * PW; }
  function yp(v){ return MT + PH - ((v - ymin) / (ymax - ymin)) * PH; }
  var lastX = xp(n - 1), lastY = yp(data[n - 1]);
  var currentVal = data[n - 1];
  var labelsLayer = [];

  CFG.bands.forEach(function(b){
    var x1 = xp(b.from), x2 = xp(b.to);
    svg.appendChild(el("rect", {x: x1, y: MT, width: x2 - x1, height: PH, fill: b.color, "fill-opacity": b.op}));
    labelsLayer.push(tx(b.label, {x: (x1 + x2) / 2, y: MT + 8, "text-anchor": "middle", "font-size": 7, "font-weight": 700, fill: b.color}));
  });

  var t, yTicks = [];
  for (t = ymin; t <= ymax; t += CFG.step) { if (Math.abs(t - currentVal) > CFG.step * 0.2) yTicks.push(t); }
  yTicks.forEach(function(v){
    svg.appendChild(el("line", {x1: margin.left, x2: margin.left + PW, y1: yp(v), y2: yp(v), stroke: "#ececec", "stroke-width": 0.5}));
    labelsLayer.push(tx(fmt(v, CFG.dig), {x: margin.left - 6, y: yp(v) + 3, "text-anchor": "end", "font-size": 8.5, fill: "#aaaaaa"}));
  });

  var refYs = [];
  CFG.refs.forEach(function(r){
    var ry = yp(r.v);
    refYs.push(ry);
    svg.appendChild(el("line", {x1: margin.left, x2: margin.left + PW, y1: ry, y2: ry, stroke: r.color, "stroke-width": 1, "stroke-dasharray": "3,3"}));
    if (Math.abs(r.v - currentVal) / currentVal >= 0.03) {
      labelsLayer.push(tx(r.label, {x: margin.left + 10, y: ry - 10, "text-anchor": "start", "font-size": 7, "font-weight": 700, fill: r.color}));
    }
  });

  var d = "";
  data.forEach(function(v, i){ d += (i === 0 ? "M" : "L") + xp(i).toFixed(2) + " " + yp(v).toFixed(2) + " "; });
  svg.appendChild(el("path", {d: d, fill: "none", stroke: "#4a5568", "stroke-width": 1.6, "stroke-linejoin": "round"}));

  svg.appendChild(el("line", {x1: margin.left, x2: margin.left, y1: MT, y2: MT + PH, stroke: "#d8d8d8", "stroke-width": 1}));
  svg.appendChild(el("line", {x1: margin.left, x2: margin.left + PW, y1: MT + PH, y2: MT + PH, stroke: "#d8d8d8", "stroke-width": 1}));

  CFG.lblIdx.forEach(function(i, k){
    var anchor = (i === 0) ? "start" : (i === n - 1 ? "end" : "middle");
    labelsLayer.push(tx(CFG.labels[i], {x: xp(i), y: MT + PH + 14, "text-anchor": anchor, "font-size": 8, fill: "#999999"}));
  });

  var floorY = refYs.length ? Math.min.apply(null, refYs) - CFG.gap : MT + PH - CFG.gap;
  CFG.events.forEach(function(ev){
    var ex = xp(ev.i);
    svg.appendChild(el("line", {x1: ex, x2: ex, y1: MT, y2: MT + PH, stroke: "#1a3560", "stroke-opacity": 0.5, "stroke-width": 1, "stroke-dasharray": "2,3"}));
    var crowded = CFG.events.some(function(o){ return o.i !== ev.i && Math.abs(xp(o.i) - ex) < 85; });
    var longest = 0;
    ev.lines.forEach(function(l){ longest = Math.max(longest, Math.ceil(l.length * 7 * 0.68)); });
    var nearRight = (ex + longest + 3) > (margin.left + PW);
    var anchor = (crowded || nearRight) ? "end" : "start";
    var lx = (anchor === "end") ? ex - 3 : ex + 3;
    var yStart = floorY - (ev.lines.length - 1) * 9 - (crowded ? 30 : 0);
    ev.lines.forEach(function(l, k){
      labelsLayer.push(tx(l, {x: lx, y: yStart + k * 9, "text-anchor": anchor, "font-size": 7, "font-weight": 700, fill: "#1a3560"}));
    });
  });

  svg.appendChild(el("circle", {cx: lastX, cy: lastY, r: 4, fill: "#4a5568"}));

  var pillText = CFG.pill;
  var pillW = Math.ceil(pillText.length * 9 * 0.58) + 10;
  var pillH = 16;
  var pillX = lastX - pillW - 6;
  var pillY = lastY - pillH / 2;
  if (pillX < margin.left) pillX = margin.left;
  svg.appendChild(el("rect", {x: pillX, y: pillY, width: pillW, height: pillH, rx: 3, fill: "#e8a825"}));
  svg.appendChild(tx(pillText, {x: pillX + pillW / 2, y: pillY + pillH / 2 + 3.5, "text-anchor": "middle", "font-size": 9, "font-weight": 700, fill: "#111111"}));

  labelsLayer.forEach(function(e){ svg.appendChild(e); });
  _cs.parentNode.appendChild(svg);
})();
</script>
</div>
<div style="font-family:-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif;font-size:10px;color:#999;padding:4px 14px 10px;font-style:italic;">Source&nbsp;: Statistique Canada, tableau 18-10-0004 et mesures de l’inflation fondamentale de la Banque du Canada&nbsp;; taux globaux mensuels compilés par Global-Rates&nbsp;; données fondamentales de septembre via investingLive. &nbsp;|&nbsp; hdq.ca</div>
</div>
</div>
<p style="font-size:11px;color:#666;font-family:-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif;margin-top:6px;">L’écart correspond à l’IPC global sur douze mois moins l’IPC-tronq sur douze mois. En septembre, l’IPC global était de 3,1&nbsp;% et l’IPC-tronq de 1,8&nbsp;%. En février, l’écart était de moins 0,5 point.</p>
<p>L’énergie explique l’essentiel de cet écart. Les prix de l’essence étaient en hausse de 27,8&nbsp;% sur un an en septembre, selon des chiffres tirés de Statistique Canada, et les prix à la consommation hors essence ont augmenté de 2,2&nbsp;%. Les mesures fondamentales éliminent ou atténuent les plus fortes variations de prix&nbsp;; un choc sur le carburant fait donc monter l’inflation globale sans faire monter l’IPC-tronq. Le WTI livrable en décembre se négociait près de 97,92&nbsp;$&nbsp;US le 21 octobre, ce qui maintient l’effet du carburant dans les données d’octobre et de novembre.</p>
<h2>Pourquoi l’avertissement du gouverneur compte toujours</h2>
<p>Le gouverneur Tiff Macklem a déclaré à Bangkok, le 16 octobre, que «&nbsp;le risque que l’inflation s’élargisse et devienne plus persistante a augmenté&nbsp;». Cette phrase porte sur la trajectoire de l’inflation fondamentale, et non sur son niveau actuel. Un choc ponctuel sur le carburant relève le niveau des prix une seule fois. Il ne devient un problème de taux que si les entreprises et les travailleurs commencent à considérer la hausse des prix comme permanente et à l’intégrer aux salaires et aux contrats.</p>
<p>Les données de septembre ne le montrent pas encore. L’IPC-tronq et l’IPC-méd ont tous deux reculé depuis février. Le marché du travail va dans le même sens&nbsp;: l’Enquête sur la population active du 9 octobre a enregistré 68&nbsp;300 pertes nettes d’emplois et un taux de chômage de 6,5&nbsp;%. La faiblesse des embauches réduit la pression d’une inflation tirée par les salaires.</p>
<p>Les marchés ne tarifent pas cette lecture. Les swaps plaçaient la probabilité d’une hausse près de 78&nbsp;% le 20 octobre, contre environ 60&nbsp;% auparavant, selon Elias Haddad, stratège chez Brown Brothers Harriman. Cinq économistes de Bay Street sondés par Canadian Mortgage Professional s’attendaient à un maintien, et l’économiste Abbey Xu, de RBC, prévoit 2,25&nbsp;% jusqu’à la fin de 2026. Les données disponibles appuient les économistes. Une hausse serait un pari sur un élargissement que le rapport de septembre ne montre pas.</p>
<h2>La transmission aux hypothèques et au dollar</h2>
<p>Une hausse atteint les ménages en deux temps. Les hypothèques et les marges de crédit à taux variable sont réajustées immédiatement, car elles sont fixées à partir du taux directeur. Les taux hypothécaires fixes réagissent aux rendements des obligations du gouvernement du Canada, qui tendent à bouger selon les attentes de hausse&nbsp;; une partie d’une décision est donc souvent déjà intégrée aux prix avant son arrivée.</p>
<p>La devise ajoute un second canal. La Réserve fédérale a relevé sa fourchette cible le 16 septembre à 3,75&nbsp;% à 4,00&nbsp;%, ce qui la place de 1,50 à 1,75 point de pourcentage au-dessus du taux de la Banque du Canada. Le dollar canadien se négociait près de 71,08&nbsp;cents US le 21 octobre, et le USD/CAD est passé à 1,4106 contre 1,4075 après la publication de l’IPC. Un dollar plus faible renchérit les importations, ce qui se répercuterait sur le même chiffre global dont la Banque tente de faire abstraction. Le prochain rapport sur l’IPC, le 16 novembre, est le premier test pour savoir si le choc énergétique s’étend.</p>',
  '<div class="toolkit-section">
<div class="toolkit-section-label">Ce qu’ils ressentent</div>
<p>Les clients voient une inflation de 3,1&nbsp;% et une facture d’essence qui a fortement augmenté, et plusieurs supposent que la Banque du Canada doit relever ses taux. Les emprunteurs à taux variable sont anxieux à l’approche du 28 octobre. Les épargnants qui détiennent des liquidités et des CPG espèrent une hausse. Les clients qui ont lu que les swaps tarifent une hausse à 78&nbsp;% peuvent croire qu’elle est déjà décidée.</p>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Quoi dire</div>
<div class="script-box">Merci de votre appel. L’inflation globale était de 3,1&nbsp;% en septembre, et l’essentiel vient de l’essence, qui a augmenté d’environ 28&nbsp;% sur un an. Les prix hors essence ont augmenté de 2,2&nbsp;%, et les deux mesures fondamentales que la Banque du Canada surveille le plus attentivement sont toutes deux sous 2&nbsp;%. La Banque se réunit le 28 octobre, et le marché tarife une hausse à environ 78&nbsp;%, mais les économistes que nous suivons s’attendent en majorité à un maintien. Nous ne pouvons pas savoir lequel a raison&nbsp;; nous n’avons donc bâti votre plan autour d’aucun des deux. Si vous avez une dette à taux variable, je voudrais confirmer ce qu’une hausse d’un quart de point vous coûterait par mois. Si vous détenez des liquidités ou des CPG, je voudrais examiner la façon dont ils sont échelonnés. Pouvons-nous prévoir un court appel la semaine prochaine&nbsp;?</div>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Qui est touché</div>
<p><strong>Forte incidence&nbsp;:</strong> les clients qui ont une hypothèque, une marge de crédit sur valeur domiciliaire ou une marge de crédit d’entreprise à taux variable, qui ressentent une hausse du 28 octobre dès leur prochain versement.</p>
<p><strong>Incidence variable&nbsp;:</strong> les clients qui renouvelleront une hypothèque à taux fixe au cours des 12 prochains mois, dont le taux dépend de rendements obligataires qui réagissent aux attentes de hausse.</p>
<p><strong>Avantage potentiel&nbsp;:</strong> les épargnants qui détiennent des liquidités, des comptes d’épargne à intérêt élevé et des CPG à court terme, qui gagneraient davantage si les taux montaient.</p>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Liste de vérification</div>
<div class="checklist-item">Dresser la liste des clients ayant une dette à taux variable et calculer le coût mensuel d’une hausse de 0,25 point.</div>
<div class="checklist-item">Dresser la liste des clients dont l’hypothèque à taux fixe vient à échéance d’ici 12 mois et examiner leurs options de taux.</div>
<div class="checklist-item">Examiner les échelles de CPG et de liquidités des clients qui détiennent plus de 12 mois de dépenses.</div>
<div class="checklist-item">Noter les dates&nbsp;: décision de la Banque du Canada le 28 octobre à 9 h 45 HE et IPC le 16 novembre.</div>
<div class="checklist-item">Planifier des appels aux clients la semaine suivant la décision.</div>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Modèle de courriel de suivi</div>
<div class="email-box" id="respond-email">
<strong>Objet&nbsp;:</strong> Ce que l’inflation de septembre signifie pour vos taux<br><br>
Bonjour [Nom du client],<br><br>
Merci de votre appel. L’inflation de septembre s’est établie à 3,1&nbsp;%, principalement en raison de l’essence. Les prix hors essence ont augmenté de 2,2&nbsp;%, et les mesures fondamentales privilégiées par la Banque du Canada sont toutes deux sous 2&nbsp;%.<br><br>
La Banque annonce sa prochaine décision de taux le 28 octobre. Les marchés tarifent une hausse, alors que de nombreux économistes s’attendent à un maintien du taux à 2,25&nbsp;%. Votre plan ne dépend d’aucune des deux issues, et je passerai en revue vos coûts d’emprunt et vos liquidités avant la décision.<br><br>
Je propose que nous nous parlions la semaine du 2 novembre. Dites-moi quelle journée vous convient.<br><br>
[Votre nom]<br><br>
<em>La présente communication est fournie à des fins éducatives seulement et ne constitue pas un conseil en placement personnalisé.</em>
</div>
<button class="btn-copy" onclick="copyEmail(''respond-email'', this)">Copier le courriel</button>
</div>',
  '<div class="toolkit-section">
<div class="toolkit-section-label">Profils de clients à cibler</div>
<p><strong>Emprunteurs à taux variable&nbsp;:</strong> les ménages qui suivent le 28 octobre ont un paiement concret en jeu.</p>
<p><strong>Propriétaires dont l’hypothèque se renouvelle d’ici 12 mois&nbsp;:</strong> ils comparent les options à taux fixe et à taux variable pendant que le marché et les économistes divergent.</p>
<p><strong>Épargnants qui détiennent de gros soldes de liquidités&nbsp;:</strong> une hausse augmenterait leur rendement, pas un maintien&nbsp;; il leur faut donc un plan pour les deux cas.</p>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Phrase d’accroche</div>
<div class="script-box">Je vous appelle parce que l’inflation est à 3,1&nbsp;% alors que les mesures fondamentales de la Banque du Canada sont sous 2&nbsp;%, et que les emprunteurs auxquels je parle ne savent pas ce que cela signifie pour leur prochain paiement.</div>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Proposition de valeur</div>
<p>Le chiffre global et les chiffres fondamentaux racontent des histoires différentes, et la décision de taux du 28 octobre dépend de celui auquel la Banque se fie. Un emprunteur qui ne lit que les manchettes ne peut pas mesurer le risque pour une hypothèque ou une marge de crédit en particulier.</p>
<p>Le conseiller propose un test de résistance des paiements au taux actuel et avec une hausse d’un quart de point, ainsi qu’un examen des liquidités et des CPG en fonction de ce que signifierait une hausse ou un maintien.</p>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Questions de découverte</div>
<p>1. Votre hypothèque ou votre marge de crédit est-elle à taux fixe ou variable, et quand doit-elle être renouvelée&nbsp;?</p>
<p>2. Combien une hausse d’un quart de point vous coûterait-elle par mois&nbsp;?</p>
<p>3. Combien détenez-vous en liquidités ou en CPG au-delà de votre fonds d’urgence&nbsp;?</p>
<p>4. Avez-vous modifié vos plans de dépenses ou d’épargne en raison de l’inflation récente&nbsp;?</p>
<p>5. Sur qui comptez-vous pour vous expliquer une décision de la Banque du Canada&nbsp;?</p>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Modèle de courriel de prospection</div>
<div class="email-box" id="prospect-email">
<strong>Objet&nbsp;:</strong> L’inflation est à 3,1&nbsp;%, mais l’inflation fondamentale est sous 2&nbsp;%<br><br>
Bonjour [Nom du prospect],<br><br>
L’inflation globale a atteint 3,1&nbsp;% en septembre, surtout à cause de l’essence. Les mesures fondamentales que la Banque du Canada surveille le plus attentivement sont sous 2&nbsp;%. La Banque rend sa décision le 28 octobre, et les marchés et les économistes divergent sur ce qu’elle fera.<br><br>
Si cela peut vous être utile, je vous offre volontiers une conversation de 20 minutes, sans engagement, sur ce que l’une ou l’autre issue signifie pour votre hypothèque et votre épargne.<br><br>
Un court appel la semaine prochaine vous conviendrait-il&nbsp;?<br><br>
[Votre nom]<br><br>
<em>La présente communication est fournie à des fins éducatives seulement et ne constitue pas un conseil en placement personnalisé.</em>
</div>
<button class="btn-copy" onclick="copyEmail(''prospect-email'', this)">Copier le courriel</button>
</div>',
  '[{"value":"3,1 %","label":"IPC de septembre, annuel"},{"value":"1,8 %","label":"IPC-tronq sur un an"},{"value":"2,25 %","label":"Taux directeur Banque du Canada"},{"value":"78 %","label":"Hausse implicite (swaps), 20 oct."}]',
