INSERT OR REPLACE INTO articles
  (slug, desk, article_type, title, dek, brief_html, body_html, respond_html, prospect_html, key_numbers, hero_image, hero_caption, read_time, published_at, tags, toolkit_gated, sources_text, en_slug)
VALUES (
  '2026/10/23/ormuz-a-5-pour-cent-du-trafic-normal-trois-canaux-vers-les-portefeuilles-canadiens',
  'geo',
  'article',
  'Ormuz à 5 % du trafic normal : trois canaux vers les portefeuilles canadiens',
  'Quatre navires ont transité le 18 oct. contre 85 un jour typique ; un Brent à plus de 110 $ US atteint les clients par les bénéfices, le carburant et la décision de taux du 28 oct.',
  '<ul>
<li><strong>Le trafic dans Ormuz est à environ 5&nbsp;% de la normale,</strong><span> avec 4 navires le 18 octobre contre 85 un jour typique.</span></li>
<li><strong>Le Brent dépasse 110&nbsp;$&nbsp;US,</strong><span> contre environ 72&nbsp;$&nbsp;US avant le début de la guerre en février.</span></li>
<li><strong>Trois canaux atteignent les portefeuilles canadiens,</strong><span> soit les bénéfices des producteurs, le coût du carburant pour les consommateurs et la Banque du Canada.</span></li>
<li><strong>Le scénario de base est la persistance,</strong><span> la réouverture et l’escalade étant des scénarios extrêmes très éloignés l’un de l’autre.</span></li>
<li><strong>Dimensionner l’exposition compte plus qu’une prévision,</strong><span> puisque les ménages très exposés à l’énergie et ceux qui détiennent surtout des titres à revenu fixe font face à des risques opposés.</span></li>
</ul>',
  '<p>Quatre navires commerciaux ont franchi le détroit d’Ormuz le 18 octobre, contre 85 un jour typique, selon le décompte PortWatch du FMI. Le Brent s’est négocié à plus de 110&nbsp;$&nbsp;US le baril cette semaine, contre environ 72&nbsp;$&nbsp;US avant la guerre commencée en février. Pour un portefeuille canadien, la question n’est pas de savoir qui contrôle le détroit. Elle est de savoir lequel de trois canaux transmet les dommages ou les gains&nbsp;: les bénéfices du secteur de l’énergie, l’inflation à la consommation ou la Banque du Canada.</p>
<h2>Comment Ormuz atteint un portefeuille canadien</h2>
<p>Le détroit acheminait environ 20&nbsp;% du pétrole transporté par mer avant la guerre. Le décompte du trafic montre à quel point peu de ce flux circule.</p>
<div class="hdq-chart">
<div style="background:#ffffff;border:1px solid #d0d0d0;width:100%;font-family:-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif;">
<div style="background:#f5f5f5;border-bottom:1px solid #d0d0d0;padding:10px 14px;display:flex;align-items:baseline;gap:16px;flex-wrap:wrap;">
<span style="font-size:13px;font-weight:700;color:#111;letter-spacing:0.02em;">DÉTROIT D’ORMUZ&nbsp;: TRANSITS COMMERCIAUX QUOTIDIENS</span>
<span style="font-size:20px;font-weight:700;color:#111;">4</span>
<span style="font-size:13px;color:#c0392b;">&#9660; 95,3&nbsp;%</span>
<span style="font-size:11px;color:#888;margin-left:auto;">FMI PORTWATCH &nbsp;|&nbsp; 18 OCT. 2026 CONTRE JOUR TYPIQUE</span>
</div>
<div style="padding:12px 14px 8px;">
<script>
(function(){
  var _cs = document.currentScript;
  var svg = document.createElementNS("http://www.w3.org/2000/svg","svg");
  svg.setAttribute("viewBox","0 0 680 300");
  svg.setAttribute("width","100%");
  var FONT = "-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif";
  function el(tag, attrs, txt){ var e = document.createElementNS("http://www.w3.org/2000/svg", tag); for (var k in attrs) e.setAttribute(k, attrs[k]); if (txt !== undefined) e.textContent = txt; return e; }
  function tx(s, a){ a["font-family"] = FONT; return el("text", a, s); }
  var CFG = {"labels":["Jour typique","18 oct. 2026"],"values":[85,4],"colors":["#4a5568","#c0392b"],"vlabels":["85 navires","4 navires"],"step":20,"gap":8,"cap":40};
  var margin = {left: 110, right: 24, top: 18, bottom: 46};
  var PW = 680 - margin.left - margin.right;
  var PH = 300 - margin.top - margin.bottom;
  var MT = margin.top;
  var n = CFG.values.length;
  var barH = Math.min(CFG.cap, Math.floor((PH - (n - 1) * CFG.gap) / n));
  var total = n * barH + (n - 1) * CFG.gap;
  if (total > PH) throw new Error("bars exceed plot height");
  var y0 = MT + (PH - total) / 2;
  var vmax = Math.max.apply(null, CFG.values);
  var axMax = Math.ceil(vmax / CFG.step) * CFG.step;
  var plotW = PW - 70;
  function xs(v){ return margin.left + (v / axMax) * plotW; }
  var labelsLayer = [];
  var t;
  for (t = 0; t <= axMax; t += CFG.step) {
    svg.appendChild(el("line", {x1: xs(t), x2: xs(t), y1: MT, y2: MT + PH, stroke: "#ececec", "stroke-width": 0.5}));
    labelsLayer.push(tx(String(t), {x: xs(t), y: MT + PH + 14, "text-anchor": "middle", "font-size": 8, fill: "#999999"}));
  }
  CFG.values.forEach(function(v, i){
    var by = y0 + i * (barH + CFG.gap);
    svg.appendChild(el("rect", {x: margin.left, y: by, width: xs(v) - margin.left, height: barH, fill: CFG.colors[i]}));
    labelsLayer.push(tx(CFG.labels[i], {x: margin.left - 8, y: by + barH / 2 + 3, "text-anchor": "end", "font-size": 8.5, fill: "#555555"}));
    labelsLayer.push(tx(CFG.vlabels[i], {x: xs(v) + 6, y: by + barH / 2 + 3.5, "text-anchor": "start", "font-size": 9, "font-weight": 700, fill: "#111111"}));
  });
  svg.appendChild(el("line", {x1: margin.left, x2: margin.left, y1: MT, y2: MT + PH, stroke: "#d8d8d8", "stroke-width": 1}));
  svg.appendChild(el("line", {x1: margin.left, x2: margin.left + PW, y1: MT + PH, y2: MT + PH, stroke: "#d8d8d8", "stroke-width": 1}));
  labelsLayer.forEach(function(e){ svg.appendChild(e); });
  _cs.parentNode.appendChild(svg);
})();
</script>
</div>
<div style="font-family:-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif;font-size:10px;color:#999;padding:4px 14px 10px;font-style:italic;">Source&nbsp;: FMI PortWatch, décomptes des transits commerciaux dans le détroit d’Ormuz, tels que rapportés par Straits Live, 23 octobre 2026. &nbsp;|&nbsp; hdq.ca</div>
</div>
</div>
<p style="font-size:11px;color:#666;font-family:-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif;margin-top:6px;">Quatre navires commerciaux ont transité le 18 octobre, soit environ 5&nbsp;% du décompte quotidien typique de 85. Le chiffre d’un jour typique est la référence d’avant la crise rapportée par PortWatch du FMI.</p>
<p>Le premier canal est celui des bénéfices des producteurs. Le Canada est un exportateur net de pétrole, et un prix du Brent près de 113&nbsp;$&nbsp;US, rapporté le 22 octobre, soutient les flux de trésorerie des producteurs dont la production est tarifée selon la référence mondiale. Le WTI livrable en décembre se négociait près de 97,92&nbsp;$&nbsp;US le 21 octobre, soit le prix nord-américain le plus pertinent pour le brut canadien.</p>
<p>Le deuxième canal est le consommateur. L’essence était en hausse de 27,8&nbsp;% sur un an dans l’IPC de septembre, selon des chiffres tirés de Statistique Canada. Le troisième est le taux directeur. Un IPC global de 3,1&nbsp;% et une probabilité de hausse près de 78&nbsp;% dans la tarification des swaps placent la décision de la Banque du Canada du 28 octobre au cœur de cette histoire. Le même prix du pétrole fait monter à la fois les bénéfices des producteurs et les coûts des ménages.</p>
<h2>Scénario de base, escalade et réouverture</h2>
<p>Le scénario de base est la persistance&nbsp;: un détroit fermé, un prix du Brent près des niveaux de cette semaine et un marché qui traite chaque incident comme du bruit jusqu’à ce que l’offre change. Les incidents ne sont pas mineurs. L’Iran a affirmé que sept navires avaient été touchés, et le président américain Donald Trump a accusé Téhéran de simuler les frappes. Le 21 octobre, les Gardiens de la révolution iraniens ont déclaré qu’un superpétrolier avait heurté une mine au sud du détroit. Cette affirmation a été rapportée comme non confirmée.</p>
<p>Les deux scénarios extrêmes sont très éloignés. Citi a dit en avril qu’elle voyait le pétrole à 150&nbsp;$&nbsp;US si la perturbation persistait. BofA a dit en juin qu’une réouverture complète pourrait ramener la moyenne du Brent de 2026 à 82&nbsp;$&nbsp;US. Le pétrole a reculé en août sur des espoirs de réouverture, qui se sont ensuite estompés. La réouverture et l’escalade sont toutes deux possibles, et aucune n’est l’issue attendue.</p>
<p>L’or se trouve de l’autre côté de la même transaction. L’or livrable en décembre se négociait à 4&nbsp;145,20&nbsp;$&nbsp;US le 21 octobre, et le dollar canadien à environ 71,08&nbsp;cents US. Un portefeuille exposé à l’énergie et sans couverture contre une réouverture porte un risque. Un portefeuille sans exposition à l’énergie porte l’autre, par des coûts de carburant plus élevés et un taux directeur qui bouge.</p>
<h2>La conversation de planification</h2>
<p>Les clients concentrés dans l’énergie détiennent une position qui monte avec la fermeture et recule en cas de réouverture. La conversation avec le conseiller porte sur le dimensionnement de cette exposition face au scénario extrême, et non sur une prévision du détroit. Les clients à revenu fixe font face à l’inverse, car le coût du carburant et la décision du 28 octobre pèsent tous deux sur leur budget. La démarche pratique consiste à tester chaque ménage face aux deux scénarios extrêmes avant la décision, en utilisant les scénarios à 82&nbsp;$&nbsp;US et à 150&nbsp;$&nbsp;US comme bornes et non comme prévisions.</p>',
  '<div class="toolkit-section">
<div class="toolkit-section-label">Ce qu’ils ressentent</div>
<p>Les clients voient aux nouvelles un pétrole à plus de 110&nbsp;$&nbsp;US et une facture d’essence qui a fortement augmenté. Les investisseurs très exposés à l’énergie sont à la fois satisfaits et inquiets qu’une réouverture puisse effacer le gain. Les retraités à revenu fixe se sentent pris à la gorge par le carburant et l’alimentation. Certains clients croient qu’une escalade est inévitable, et d’autres qu’elle passera en une semaine.</p>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Quoi dire</div>
<div class="script-box">Merci de votre appel. Le détroit d’Ormuz voit passer environ 5&nbsp;% de son trafic commercial normal, et le Brent dépasse 110 dollars le baril, contre environ 72 avant le début de la guerre en février. Pour vous, cela atteint votre portefeuille de trois façons&nbsp;: les bénéfices des sociétés énergétiques, le prix du carburant et la décision de la Banque du Canada du 28 octobre. Je n’essaie pas de prévoir ce qui se passera dans le détroit. La réouverture et l’escalade sont toutes deux possibles, et l’écart entre les deux est large. Ce que je veux faire, c’est vérifier comment vos placements et votre budget résisteraient aux deux extrêmes, afin que rien dans votre plan ne dépende d’une conjecture. Pouvons-nous planifier une revue cette semaine&nbsp;?</div>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Qui est touché</div>
<p><strong>Forte incidence&nbsp;:</strong> les clients qui ont des positions concentrées dans l’énergie canadienne, et les retraités à revenu fixe qui consacrent une grande part de leurs dépenses au carburant et à l’alimentation.</p>
<p><strong>Incidence variable&nbsp;:</strong> les clients dont le portefeuille est équilibré, qui détiennent une exposition à l’énergie à côté de secteurs sensibles aux taux qui réagissent à la décision du 28 octobre.</p>
<p><strong>Avantage potentiel&nbsp;:</strong> les clients qui détiennent de l’or ou des titres de revenu à courte durée, qui ont bien tenu pendant que le pétrole et les attentes de taux bougeaient.</p>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Liste de vérification</div>
<div class="checklist-item">Repérer les clients dont l’exposition à l’énergie dépasse la limite fixée dans leur énoncé de politique de placement.</div>
<div class="checklist-item">Tester chaque ménage face à des scénarios de Brent à 82&nbsp;$&nbsp;US et à 150&nbsp;$&nbsp;US, comme bornes et non comme prévisions.</div>
<div class="checklist-item">Examiner les clients à revenu fixe pour déceler la pression du carburant et de l’alimentation sur leur taux de retrait.</div>
<div class="checklist-item">Confirmer que les avoirs en or ou de couverture contre l’inflation sont dimensionnés selon le plan.</div>
<div class="checklist-item">Planifier des revues pour la semaine suivant la décision de la Banque du Canada du 28 octobre.</div>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Modèle de courriel de suivi</div>
<div class="email-box" id="respond-email">
<strong>Objet&nbsp;:</strong> Le détroit d’Ormuz et votre portefeuille<br><br>
Bonjour [Nom du client],<br><br>
Merci de notre conversation. Le trafic commercial dans le détroit d’Ormuz atteint environ 5&nbsp;% de la normale, et le pétrole Brent dépasse 110&nbsp;$&nbsp;US, contre environ 72&nbsp;$&nbsp;US avant le début de la guerre en février.<br><br>
Pour votre portefeuille, l’effet passe par les bénéfices des sociétés énergétiques, le coût du carburant et la décision de la Banque du Canada du 28 octobre. Je ne prévois pas ce qui se passera dans le détroit. Je vérifierai plutôt comment vos placements et votre budget résisteraient à une forte baisse du pétrole en cas de réouverture ou à une forte hausse en cas d’escalade.<br><br>
Je propose que nous nous parlions la semaine du 2 novembre. Dites-moi quelle journée vous convient.<br><br>
[Votre nom]<br><br>
<em>La présente communication est fournie à des fins éducatives seulement et ne constitue pas un conseil en placement personnalisé.</em>
</div>
<button class="btn-copy" onclick="copyEmail(''respond-email'', this)">Copier le courriel</button>
</div>',
  '<div class="toolkit-section">
<div class="toolkit-section-label">Profils de clients à cibler</div>
<p><strong>Investisseurs concentrés dans l’énergie&nbsp;:</strong> investisseurs autonomes, surtout dans l’Ouest canadien, qui détiennent une grande part de leur portefeuille dans des sociétés pétrolières et gazières.</p>
<p><strong>Retraités à revenu fixe&nbsp;:</strong> ménages dont le carburant et l’alimentation représentent une grande part des dépenses et qui n’ont pas de plan face à l’inflation.</p>
<p><strong>Propriétaires d’entreprises de transport et de fabrication&nbsp;:</strong> propriétaires dont les coûts d’intrants montent avec le carburant et qui détiennent leur patrimoine personnel dans les mêmes secteurs.</p>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Phrase d’accroche</div>
<div class="script-box">Je vous appelle parce que le pétrole dépasse 110 dollars le baril, avec un détroit d’Ormuz à environ 5&nbsp;% du trafic normal, et que les investisseurs auxquels je parle se demandent s’ils doivent ajouter à l’énergie ou la réduire.</div>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Proposition de valeur</div>
<p>Un prix du pétrole qui monte avec une fermeture et pourrait chuter à la réouverture est un risque de concentration pour un portefeuille très exposé à l’énergie. Un investisseur qui gère seul a tendance à extrapoler la dernière manchette.</p>
<p>Le conseiller propose un test de scénarios aux deux bornes publiées, un Brent à 82&nbsp;$&nbsp;US et à 150&nbsp;$&nbsp;US, ainsi qu’un plan qui tient à l’une comme à l’autre.</p>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Questions de découverte</div>
<p>1. Quelle part de votre portefeuille est investie dans des sociétés énergétiques canadiennes&nbsp;?</p>
<p>2. Comment vous sentiriez-vous si le pétrole reculait de 25&nbsp;% à la réouverture&nbsp;?</p>
<p>3. Quelle part de vos dépenses mensuelles va au carburant et à l’alimentation&nbsp;?</p>
<p>4. Détenez-vous quelque chose qui monterait si le pétrole continuait de grimper&nbsp;?</p>
<p>5. Avez-vous un plan écrit pour rééquilibrer une position trop importante&nbsp;?</p>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Modèle de courriel de prospection</div>
<div class="email-box" id="prospect-email">
<strong>Objet&nbsp;:</strong> Pétrole à plus de 110&nbsp;$&nbsp;US&nbsp;: ce que cela signifie pour votre portefeuille<br><br>
Bonjour [Nom du prospect],<br><br>
Le trafic commercial dans le détroit d’Ormuz atteint environ 5&nbsp;% de la normale, et le Brent dépasse 110&nbsp;$&nbsp;US. Pour les investisseurs canadiens, cela fait monter en même temps les bénéfices des sociétés énergétiques et le coût du carburant, et cela s’inscrit dans la décision de la Banque du Canada du 28 octobre.<br><br>
Si cela peut vous être utile, je vous offre volontiers une conversation de 20 minutes, sans engagement, sur la façon dont votre portefeuille résisterait aux deux extrémités de la fourchette.<br><br>
Un court appel la semaine prochaine vous conviendrait-il&nbsp;?<br><br>
[Votre nom]<br><br>
<em>La présente communication est fournie à des fins éducatives seulement et ne constitue pas un conseil en placement personnalisé.</em>
</div>
<button class="btn-copy" onclick="copyEmail(''prospect-email'', this)">Copier le courriel</button>
</div>',
  '[{"value":"4","label":"Transits dans Ormuz le 18 oct."},{"value":"85","label":"Transits quotidiens typiques"},{"value":"113 $ US","label":"Brent, 22 oct."},{"value":"72 $ US","label":"Brent avant la guerre"}]',
  'geo-140.jpg',
  'La navigation dans le détroit d’Ormuz achemine une grande part du commerce pétrolier mondial par voie maritime, et toute perturbation s’y répercute sur les marchés canadiens de l’énergie et du carburant. Photo : iStock.',
  5,
  '2026-10-23T09:00:00',
  'entity:iran,entity:hormuz,entity:brent,entity:tsx-energy,theme:hormuz-disruption,theme:cdn-energy-rerating,stance:base-case',
  1,
  'FMI PortWatch, décomptes des transits dans le détroit d’Ormuz, tels que rapportés par Straits Live (synthèse assistée par IA), 23 octobre 2026 ; Rio Times, 21 octobre 2026 ; The Hill et gCaptain, reportages sur les incidents de navires et la réponse américaine ; La Presse Canadienne, clôture des marchés du 21 octobre (WTI, or, dollar canadien) ; Statistique Canada via PaycheckGuru, essence dans l’IPC de septembre ; Energy Now (Citi, avril 2026) et BOE Report (BofA, 18 juin 2026), titres de prévisions ; Brown Brothers Harriman via FXStreet, 20 octobre.',
  '2026/10/23/hormuz-at-five-percent-of-normal-traffic-three-channels-into-canadian-portfolios'
);
INSERT OR REPLACE INTO articles
  (slug, desk, article_type, title, dek, brief_html, body_html, respond_html, prospect_html, key_numbers, hero_image, hero_caption, read_time, published_at, tags, toolkit_gated, sources_text, en_slug)
VALUES (
  '2026/10/23/le-tsx-cede-27-pour-cent-de-son-rebond-le-brent-cloture-a-113-dollars-us-et-les-materiaux-glissent',
  'market',
  'article',
  'Le TSX cède 27 % de son rebond, le Brent clôture à 113 $ US et les matériaux glissent',
  'Le TSX a perdu 0,97 % à 35 973,45, le Nasdaq 2,60 % sur des doutes quant aux dépenses en IA, et le brut son plus haut cours de clôture depuis le 4 mai.',
  '<ul>
<li><strong>Le TSX a reculé de 0,97&nbsp;% à 35&nbsp;973,45,</strong><span> cédant 27&nbsp;% de sa remontée depuis le creux du 7 octobre.</span></li>
<li><strong>Les matériaux ont mené le repli,</strong><span> l’or perdant 89,60&nbsp;$&nbsp;US et le cuivre touchant un creux de cinq semaines.</span></li>
<li><strong>Le Brent a clôturé à 113,17&nbsp;$&nbsp;US,</strong><span> en hausse de 4,00&nbsp;% et au plus haut cours de clôture depuis le 4 mai.</span></li>
<li><strong>Le Nasdaq a reculé de 2,60&nbsp;% sur des doutes quant aux dépenses en IA,</strong><span> sa plus forte baisse depuis juin.</span></li>
<li><strong>Le rendement américain à 10 ans a reculé de 17 points de base à 4,96&nbsp;%,</strong><span> sa plus forte baisse depuis mars 2023.</span></li>
</ul>',
  '<p>L’indice composé S&amp;P/TSX a reculé de 351,54 points, soit 0,97&nbsp;%, à 35&nbsp;973,45 jeudi, cédant 27&nbsp;% de la remontée de 1&nbsp;283 points depuis le creux de 35&nbsp;041,86 du 7 octobre. Le Brent a clôturé à 113,17&nbsp;$&nbsp;US, en hausse de 4,00&nbsp;% et au plus haut cours de clôture depuis le 4 mai. Les actions canadiennes et le pétrole ont évolué en sens opposés le même jour, et cet écart venait de deux chocs distincts&nbsp;: une glissade des métaux à Toronto et une vente massive liée aux dépenses en IA à New York.</p>
<h2>Pourquoi les matériaux ont tiré le TSX vers le bas pendant que le pétrole montait</h2>
<p>Les matériaux ont mené le repli, en baisse de 4,4&nbsp;% selon les rapports de marché. L’or livrable en décembre a perdu 89,60&nbsp;$&nbsp;US pour s’établir à 4&nbsp;060,40&nbsp;$&nbsp;US l’once, et le cuivre a touché un creux de cinq semaines en raison de la hausse des stocks. Les valeurs technologiques canadiennes ont reculé de 1,5&nbsp;%, Celestica perdant 7,2&nbsp;% après que Meta a divulgué d’importants engagements de dépenses. Mullen Group a gagné 8,0&nbsp;% après avoir dépassé les attentes trimestrielles.</p>
<p>Le dollar canadien est passé à 71,32&nbsp;cents US contre 71,14 mercredi&nbsp;; la devise n’a donc pas accentué les ventes.</p>
<p>Trois des six marchés suivis ici ont reculé. Les gains sont venus du Dow, en hausse de 0,02&nbsp;%, et de deux contrats de brut.</p>
<div class="hdq-chart">
<div style="background:#ffffff;border:1px solid #d0d0d0;width:100%;font-family:-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif;">
<div style="background:#f5f5f5;border-bottom:1px solid #d0d0d0;padding:10px 14px;display:flex;align-items:baseline;gap:16px;flex-wrap:wrap;">
<span style="font-size:13px;font-weight:700;color:#111;letter-spacing:0.02em;">CLÔTURE DU 22 OCT.&nbsp;: VARIATION EN POURCENTAGE PAR MARCHÉ</span>
